class Solution:
    def minCost(self, n: int, m: int) -> int:
        N = 10000
        comp = [False] * N; comp[0] = comp[1] = True
        for p in range(2, N):
            if not comp[p]:
                for q in range(p * p, N, p): comp[q] = True
        if comp[n] or comp[m]: return -1
        import heapq
        d = len(str(n))
        lo = 10 ** (d - 1) if d > 1 else 1
        hi = 10 ** d - 1
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            c, u = heapq.heappop(pq)
            if u == m: return c
            if c > dist.get(u, 1 << 60): continue
            s = str(u)
            for i in range(d):
                for delta in (1, -1):
                    nd = int(s[i]) + delta
                    if nd < 0 or nd > 9 or (i == 0 and nd == 0): continue
                    v = int(s[:i] + str(nd) + s[i+1:])
                    if lo <= v <= hi and not comp[v] and c + v < dist.get(v, 1 << 60):
                        dist[v] = c + v
                        heapq.heappush(pq, (c + v, v))
        return -1

