class Solution {
public:
    int minCost(int n, int m) {
        const int N = 10000;
        vector<bool> comp(N, false); comp[0] = comp[1] = true;
        for (int p = 2; p < N; p++)
            if (!comp[p]) for (int q = p * p; q < N; q += p) comp[q] = true;
        if (comp[n] || comp[m]) return -1;
        int d = to_string(n).size();
        long long lo = (d > 1) ? (long long)pow(10, d - 1) : 1, hi = (long long)pow(10, d) - 1;
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        unordered_map<int,long long> dist; dist[n] = n; pq.push({n, n});
        while (!pq.empty()) {
            auto [c, u] = pq.top(); pq.pop();
            if (u == m) return (int)c;
            auto it = dist.find(u);
            if (it == dist.end() || c > it->second) continue;
            string s = to_string(u);
            for (int i = 0; i < d; i++) for (int dl : {-1, 1}) {
                int nd = s[i] - '0' + dl;
                if (nd < 0 || nd > 9 || (i == 0 && nd == 0)) continue;
                string t = s; t[i] = '0' + nd;
                long long v = stoll(t);
                if (v < lo || v > hi || comp[v]) continue;
                auto jt = dist.find(v);
                if (jt == dist.end() || c + v < jt->second) {
                    dist[v] = c + v; pq.push({c + v, (int)v});
                }
            }
        }
        return -1;
    }
};

