class Solution {
    public int minCost(int n, int m) {
        int N = 10000;
        boolean[] comp = new boolean[N]; comp[0] = comp[1] = true;
        for (int p = 2; p < N; p++)
            if (!comp[p]) for (int q = p * p; q < N; q += p) comp[q] = true;
        if (comp[n] || comp[m]) return -1;
        int d = String.valueOf(n).length();
        long lo = d > 1 ? (long) Math.pow(10, d - 1) : 1, hi = (long) Math.pow(10, d) - 1;
        Map<Integer, Long> dist = new HashMap<>(); dist.put(n, (long) n);
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{n, n});
        while (!pq.isEmpty()) {
            long[] top = pq.poll(); long c = top[0]; int u = (int) top[1];
            if (u == m) return (int) c;
            Long du = dist.get(u);
            if (du == null || c > du) continue;
            char[] s = String.valueOf(u).toCharArray();
            for (int i = 0; i < d; i++) for (int dl : new int[]{1, -1}) {
                int nd = s[i] - '0' + dl;
                if (nd < 0 || nd > 9 || (i == 0 && nd == 0)) continue;
                char[] t = s.clone(); t[i] = (char) ('0' + nd);
                long v = Long.parseLong(new String(t));
                if (v < lo || v > hi || comp[(int) v]) continue;
                Long dv = dist.get((int) v);
                if (dv == null || c + v < dv) { dist.put((int) v, c + v); pq.add(new long[]{c + v, v}); }
            }
        }
        return -1;
    }
}

