var minCost = function(n, m) {
    const N = 10000;
    const comp = Array(N).fill(false); comp[0] = comp[1] = true;
    for (let p = 2; p < N; p++)
        if (!comp[p]) for (let q = p * p; q < N; q += p) comp[q] = true;
    if (comp[n] || comp[m]) return -1;
    const d = String(n).length;
    const lo = d > 1 ? 10 ** (d - 1) : 1, hi = 10 ** d - 1;
    const dist = new Map([[n, n]]);
    const pq = [[n, n]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [c, u] = pq.shift();
        if (u === m) return c;
        if (c > (dist.get(u) ?? Infinity)) continue;
        const s = String(u);
        for (let i = 0; i < d; i++) for (const dl of [1, -1]) {
            const nd = +s[i] + dl;
            if (nd < 0 || nd > 9 || (i === 0 && nd === 0)) continue;
            const v = +(s.slice(0, i) + nd + s.slice(i + 1));
            if (v < lo || v > hi || comp[v]) continue;
            if (c + v < (dist.get(v) ?? Infinity)) { dist.set(v, c + v); pq.push([c + v, v]); }
        }
    }
    return -1;
};
